async function eeGet(obj) {
  return await new Promise((resolve, reject) => {
    obj.evaluate((v, err) => {
      if (err) reject(err);
      else resolve(v);
    });
  });
}

function s2Joined(start, end, region) {
  const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate(start, end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
  const s2c = ee.ImageCollection('COPERNICUS/S2_CLOUD_PROBABILITY')
    .filterBounds(region)
    .filterDate(start, end);
  const joined = ee.ImageCollection(ee.Join.saveFirst('clouds').apply({
    primary: s2,
    secondary: s2c,
    condition: ee.Filter.equals({leftField: 'system:index', rightField: 'system:index'})
  }));
  return joined;
}

function maskS2(img) {
  const cloudsImg = ee.Image(img.get('clouds'));
  const qa = img.select('QA60');
  const qaCloud = qa.bitwiseAnd(1 << 10).eq(0).and(qa.bitwiseAnd(1 << 11).eq(0));
  const probMask = ee.Image(ee.Algorithms.If(
    ee.Algorithms.IsEqual(cloudsImg, null),
    ee.Image(1),
    cloudsImg.select('probability').lt(40)
  ));
  const mask = qaCloud.and(probMask);
  return img.updateMask(mask);
}

function ndviS2(imgMasked) {
  return imgMasked.normalizedDifference(['B8', 'B4']).rename('NDVI');
}

function landsat8Col(start, end, region) {
  return ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filterDate(start, end)
    .filter(ee.Filter.lt('CLOUD_COVER', 80));
}

function maskScaleL8(img) {
  const qa = img.select('QA_PIXEL');
  const mask = qa.bitwiseAnd(1 << 3).eq(0) // Cloud
    .and(qa.bitwiseAnd(1 << 4).eq(0)) // Cloud shadow
    .and(qa.bitwiseAnd(1 << 1).eq(0)) // Dilated cloud
    .and(qa.bitwiseAnd(1 << 2).eq(0)); // Cirrus
  const optical = img.select(['SR_B2','SR_B3','SR_B4','SR_B5'])
    .multiply(0.0000275).add(-0.2);
  return optical.updateMask(mask).copyProperties(img, img.propertyNames());
}

function ndviL8(imgMasked) {
  return imgMasked.normalizedDifference(['SR_B5','SR_B4']).rename('NDVI');
}

async function pickImageStatsS2(targetDateStr, region, windowDays) {
  const target = ee.Date(targetDateStr);
  const start = target.advance(-windowDays, 'day');
  const end = target.advance(windowDays + 1, 'day');
  let col = s2Joined(start, end, region)
    .map(img => img.set('diffDays', ee.Number(img.date().difference(target, 'day')).abs()))
    .sort('diffDays');
  const size = await eeGet(col.size());
  if (!size || size === 0) return {status: 'EMPTY', tried: 'S2', size: 0};
  const list = col.toList(10);
  const n = Math.min(10, size);
  for (let i = 0; i < n; i++) {
    const img = ee.Image(list.get(i));
    const dateStr = await eeGet(ee.Date(img.get('system:time_start')).format('YYYY-MM-dd'));
    const preCountDict = img.select('B8').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    });
    const preCount = await eeGet(preCountDict.get('B8')) || 0;
    const masked = maskS2(img);
    const ndvi = ndviS2(masked);
    const validCountDict = ndvi.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    });
    const validCount = await eeGet(validCountDict.get('NDVI')) || 0;
    if (validCount > 0) {
      const meanDict = ndvi.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      });
      const meanNDVI = await eeGet(meanDict.get('NDVI'));
      if (meanNDVI === null || isNaN(meanNDVI) || meanNDVI < -1.0 || meanNDVI > 1.0) {
        return {status: 'C3'};
      }
      const cloudPct = preCount > 0 ? (1 - (validCount / preCount)) * 100.0 : null;
      return {
        status: 'OK',
        source: 'S2',
        dateStr,
        preCount,
        validCount,
        cloudPct,
        meanNDVI: meanNDVI
      };
    }
  }
  return {status: 'NOVALID', tried: 'S2', size};
}

