async function getStatsForDate(targetDateStr, region) {
  // Try S2 ±5 days, then ±15, then L8 ±15
  let res = await pickImageStatsS2(targetDateStr, region, 5);
  if (res.status === 'OK' || res.status === 'C3') return res;
  if (res.status === 'EMPTY' || res.status === 'NOVALID') {
    let res2 = await pickImageStatsS2(targetDateStr, region, 15);
    if (res2.status === 'OK' || res2.status === 'C3') return res2;
    // Fallback to Landsat 8
    let res3 = await pickImageStatsL8(targetDateStr, region, 15);
    if (res3.status === 'OK' || res3.status === 'C3') return res3;
    if (res2.status === 'EMPTY' && res3.status === 'EMPTY') return {status: 'C1'};
    return {status: 'C2'}; // images exist but no valid pixels after masking
  }
  return {status: 'D'}; // unexpected
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const windhoek = ee.Geometry.Point([17.083, -22.560]);
    const region = windhoek.buffer(20000); // 20 km radius
    const dateA = '2020-01-29';
    const dateB = '2021-02-07';

    // 2. Data Acquisition & Processing per date
    const statsA = await getStatsForDate(dateA, region);
    const statsB = await getStatsForDate(dateB, region);

    // 3. Handle error cases
    if (statsA.status === 'C1' || statsB.status === 'C1') {
      console.log('One or both windows: Empty Collection.');
      console.log('C1');
      return;
    }
    if (statsA.status === 'C2' || statsB.status === 'C2') {
      console.log('Images exist but 0 valid pixels after masking in at least one window.');
      console.log('C2');
      return;
    }
    if (statsA.status === 'C3' || statsB.status === 'C3') {
      console.log('Computation invalid (null/NaN/out-of-range).');
      console.log('C3');
      return;
    }
    if (statsA.status !== 'OK' || statsB.status !== 'OK') {
      console.log('Processing failure or API issue.');
      console.log('D');
      return;
    }

    // 4. Print concise evidence (<=20 lines)
    const lineA = `Ref 2020-01-29 -> Used ${statsA.source} on ${statsA.dateStr}; imgs valid px: ${statsA.validCount}/${statsA.preCount}; cloud%: ${statsA.cloudPct !== null ? statsA.cloudPct.toFixed(1) : 'NA'}; mean NDVI: ${statsA.meanNDVI.toFixed(3)}`;
    const lineB = `Ref 2021-02-07 -> Used ${statsB.source} on ${statsB.dateStr}; imgs valid px: ${statsB.validCount}/${statsB.preCount}; cloud%: ${statsB.cloudPct !== null ? statsB.cloudPct.toFixed(1) : 'NA'}; mean NDVI: ${statsB.meanNDVI.toFixed(3)}`;
    const diff = statsB.meanNDVI - statsA.meanNDVI;
    console.log(lineA);
    console.log(lineB);
    console.log(`NDVI Δ (2021-02-07 minus 2020-01-29): ${diff.toFixed(3)}`);

    // 5. Final Answer
    if (statsB.meanNDVI > statsA.meanNDVI) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.error('Error:', err);
    console.log('D');
  }
}

